package servlet;
import java.io.IOException;import java.sql.SQLException;import java.time.*;import java.time.format.DateTimeParseException;import javax.servlet.*;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import model.dao.*;import model.entity.*;import util.WebSupport;
@WebServlet(urlPatterns={"/task-register","/task-register-result-servlet"}) public class TaskRegisterServlet extends HttpServlet {private static final long serialVersionUID=1L;
 @Override protected void doGet(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{showForm(q,p,null,null);}
 @Override protected void doPost(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{q.setCharacterEncoding("UTF-8");TaskBean b=read(q);if(q.getServletPath().equals("/task-register")){showForm(q,p,b,null);return;}String err=validate(q,b);if(err!=null){WebSupport.error(q,err);showForm(q,p,b,err);return;}try{if(new TaskDAO().insert(b)!=1){WebSupport.error(q,"E007");failure(q,p,b);return;}TaskBean saved=new TaskDAO().findById(b.getTaskId());q.setAttribute("task",saved);q.setAttribute("message",WebSupport.message("I001"));WebSupport.forward(q,p,"task-register-success.jsp");}catch(SQLException e){WebSupport.log(getServletContext(),e);WebSupport.error(q,"E007");failure(q,p,b);}}
 private TaskBean read(HttpServletRequest q){TaskBean b=new TaskBean();b.setTaskName(q.getParameter("taskName"));b.setMemo(q.getParameter("memo"));b.setUserId(q.getParameter("userId"));b.setStatusCode(q.getParameter("statusCode"));try{b.setCategoryId(Integer.parseInt(q.getParameter("categoryId")));}catch(Exception ignored){b.setCategoryId(-1);}try{String d=q.getParameter("limitDate");b.setLimitDate(d==null||d.isBlank()?null:LocalDate.parse(d));}catch(Exception ignored){q.setAttribute("invalidDate",true);}return b;}
 private String validate(HttpServletRequest q,TaskBean b){String d=q.getParameter("limitDate");if(!WebSupport.required(b.getTaskName()))return "E001";if(b.getTaskName().trim().length()>50||(b.getMemo()!=null&&b.getMemo().length()>100))return "E002";if(Boolean.TRUE.equals(q.getAttribute("invalidDate"))||b.getCategoryId()<1||b.getUserId()==null||b.getStatusCode()==null)return "E003";if(b.getLimitDate()!=null&&b.getLimitDate().isBefore(LocalDate.now()))return "E004";try{if(!new CategoryDAO().selectAllCategory().stream().anyMatch(x->x.getCategoryId()==b.getCategoryId())||!new UserDAO().selectAllUser().stream().anyMatch(x->x.getUserId().equals(b.getUserId()))||!new StatusDAO().exists(b.getStatusCode()))return "E003";}catch(SQLException e){WebSupport.log(getServletContext(),e);return "E013";}return null;}
 private void showForm(HttpServletRequest q,HttpServletResponse p,TaskBean b,String err)throws ServletException,IOException{try{q.setAttribute("categories",new CategoryDAO().selectAllCategory());q.setAttribute("statuses",new StatusDAO().selectAllStatus());q.setAttribute("users",new UserDAO().selectAllUser());q.setAttribute("task",b);if(err!=null)q.setAttribute("errorId",err);WebSupport.forward(q,p,"task-register.jsp");}catch(SQLException e){WebSupport.log(getServletContext(),e);WebSupport.error(q,"E013");WebSupport.forward(q,p,"task-register.jsp");}}
 private void failure(HttpServletRequest q,HttpServletResponse p,TaskBean b)throws ServletException,IOException{q.setAttribute("task",b);WebSupport.forward(q,p,"task-register-failure.jsp");}
}
